fn solve(a: i8) -> i8 {
    // We know `a` is in the range [0, 127].
    // Count how many octal digits equal to 1.
    let mut v = a as u8;
    let mut count: i8 = 0;

    while v > 0 {
        if v % 8 == 1 {
            count += 1;
        }
        v /= 8;
    }

    count
}

